    internal static class SelfKnow
    {
#if CROSS
        private static readonly Regex Question = new Regex(@"^(?:(?:hey|hi|please|so|capri) )*(what|whats|how|why|where|which|can|could|does|do|is|are|explain|tell me|show me|give me|teach me|help|tutorial|guide|walkthrough|i want|i need)\b");

        private static string Plain(string text)
        {
            return Regex.Replace((text ?? "").ToLowerInvariant().Replace("'", "").Replace("\u2019", ""), @"[^a-z0-9]+", " ").Trim();
        }

        private static bool Asks(string text, string phrases)
        {
            foreach (string words in phrases.Split('|'))
                if ((" " + text + " ").IndexOf(" " + words + " ", StringComparison.Ordinal) >= 0) return true;
            return false;
        }

        internal static string Matching(string asked, Hands.Kit kit = null)
        {
            string news = News.Matching(asked);
            if (news != null) return news;
            string text = Plain(asked);
            if (!Question.IsMatch(text) || Files.PathIn(asked) != null) return null;
            List<string> found = new List<string>();
            if (Asks(text, "find files|find a folder|find game folders|finding files|file search"))
                found.Add("Finding files: She searches names on a worker, using Spotlight on Mac or walking their home folder on Linux, then drives mounted in /media, /run/media or /mnt when home has no match. Results show full paths, closest first. Say show it to me or open that folder to select it in Finder on Mac or open its folder on Linux. Stop cancels the search. She does not read file contents to search.");
            if (Asks(text, "website nicknames|website aliases|remember a website|name a website"))
                found.Add("Website nicknames: Say remember apples is example.com/page, open apples, what websites do you know, or forget the apples website. Nicknames are in websites.json in her data folder. " + (Hands.OnMac ? "She reads Safari, Chrome, Edge, Brave and Arc addresses without moving input, with macOS Automation permission. For other browsers, give the address." : "Give the address when saving a nickname. She cannot read the front browser's address on Linux."));
            if (Asks(text, "new move|new moves|add a move|make a move|make a new move|custom move|custom moves|custom animation|custom animations|skin moves|moves from skins|what moves can you do|which moves can you do|moves can you do"))
                found.Add("New moves: " + MovesFacts());
            if (Asks(text, "handing her a file|hand you a file|give you a file|drop a file|drag a file|attach a file|read a file|read files|files can you read|files do you read|file types|file formats|read a pdf|read a spreadsheet"))
                found.Add("Handing her a file: Drag a file onto Capri, or ask read followed by its full path; quote spaces. Mod and plug-in files dropped on their own go to Import mod instead, after she asks. She reads text, code, Word .docx and Excel .xlsx. PDFs use PDFKit on Mac or Poppler on Linux, up to four pages at a time; scanned pages need OCR, which is unavailable here. Pictures use the selected brain when it can see; there is no local OCR fallback. Use page for PDFs and offset to continue text. Only named or handed paths can be read. Contents stay as data for a few follow-up turns and cannot authorize tools.");
            if (Asks(text, "your plug ins|your plugins|capri plug ins|capri plugins|claude plug ins|claude plugins|claude plugin|mcp server|mcp servers|what are plug ins|what are plugins|what is a plug in|what is a plugin|whats a plug in|whats a plugin|import a plug in|import a plugin|starter plug ins|starter plugins|use notion|use linear|connect notion|connect linear|sign in to notion|sign in to linear|set up email|email plug in|email plugin|outlook email|outlook account|outlook work|hotmail"))
                found.Add("Plug-ins: A plug-in gives her tools from MCP servers, like Claude's plug-ins, and can bring skills she reads when they fit. In Mainframe > Mods, Import mod takes a .capri-plugin, or a Claude plug-in's plugin.json or a .mcp.json, and her Turn on this plug-in? box shows what it starts or connects to before it's on. Email, Notion and Linear wait there as starters, off until you switch one on. Email opens Set up Email for your address and an app password. Outlook.com, Hotmail and Live addresses don't work: " + MailAccount.OutlookNote + " Her email signs in only with a password, over IMAP and SMTP, and has no Microsoft sign-in. Notion and Linear open your browser to sign in, and a row that says Turn it off and on to sign in still needs you. On this system she keeps sign-ins and the email app password only until she closes. Her plug-in tools ask first the way your SECURITY settings say, and she always asks before she sends an email.");
            return found.Count == 0 ? null : string.Join("\n", found.ToArray());
        }
#else
        internal sealed class Topic
        {
            internal readonly string Name;
            internal readonly string PlainName;
            internal readonly string[] Words;
            internal readonly string Facts;
            internal readonly string File;
            internal readonly string Label;
            // Facts made from her tools here, for topics about what she can do.
            private readonly Func<Hands.Kit, string> made;

            internal Topic(string name, string words, string facts, string file, string label)
            {
                Name = name;
                PlainName = Plain(name);
                Words = words.Split('|');
                Facts = facts;
                File = file;
                Label = label;
            }

            internal Topic(string name, string words, Func<Hands.Kit, string> made, string file, string label) : this(name, words, (string)null, file, label) { this.made = made; }

            internal string FactsFor(Hands.Kit kit) { return made == null ? Facts : made(kit); }
        }

